//! Detailed explanations moved out of the first-read cards.
pub(super) fn detail(code: &str) -> Option<&'static str> {
    Some(match code {
        "E_PRODUCTION_ROSTER" => "# E_PRODUCTION_ROSTER\n\nE_PRODUCTION_ROSTER means the saved production roster is unsafe, changed, or cannot log in as its known principal. Inspect the roster and deployment. Keep credentials with their store; use stable arguments and never silently create replacement accounts. See snapback4 guide staging.",
        "E_PRODUCTION_ROSTER_BUSY" => "# E_PRODUCTION_ROSTER_BUSY\n\nE_PRODUCTION_ROSTER_BUSY means the named production roster has an exclusive setup lock. Wait for its driver. After confirming an interrupted driver is gone, inspect partial grants and remove only that roster lock; setup is not rolled back. See snapback4 guide staging.",
        "E_DATA_TRANSACTION_ABORTED" => "# E_DATA_TRANSACTION_ABORTED\n\nE_DATA_TRANSACTION_ABORTED means postgres confirmed that the early-release data transaction aborted after acknowledged drainage. No success receipt is issued. Inspect the server outcome and retry through the identified-write path with the original intent id. See snapback4 guide deploy.",
        "E_DEV_ACCOUNTS" => "# E_DEV_ACCOUNTS\n\nE_DEV_ACCOUNTS means development account setup requires startDev with password identity. Use devAccounts only on development; seedAccounts for staging and provisionAccounts for production. guide staging.",
        "E_SERVE_STOP_FAILED" => "# E_SERVE_STOP_FAILED\n\nE_SERVE_STOP_FAILED means the npm serve script exited unsuccessfully during shutdown. Inspect shutdown handlers; a successful proof command cannot clear this failure. guide testing.",
        "E_SERVE_THEN_FAILED" => "# E_SERVE_THEN_FAILED\n\nE_SERVE_THEN_FAILED means the serve proof callback failed. Cleanup still checks group shutdown and lock release; repair the callback and rerun. guide testing.",
        "E_SERVE_THEN_TIMEOUT" => "# E_SERVE_THEN_TIMEOUT\n\nE_SERVE_THEN_TIMEOUT means the serve proof command or callback exceeded thenTimeoutMs. Inspect stuck work; commands are stopped with the owned serve group, callbacks must honor their signal. guide testing.",
        "E_WITNESS_ARGUMENTS" => "# E_WITNESS_ARGUMENTS\n\nE_WITNESS_ARGUMENTS means beginForm expected must be an argument constraint object or null for dynamic arguments. Named values are compared exactly; handler-owned additional keys are allowed. guide testing.",
        "E_SERVE_CHECK" => "# E_SERVE_CHECK\n\nE_SERVE_CHECK means the serve-check invocation or owned-process inspection failed. Check options with serve-check --help and rerun. No passing script qualification is claimed. See snapback4 guide testing.",
        "E_SERVE_CHECK_PLATFORM" => "# E_SERVE_CHECK_PLATFORM\n\nE_SERVE_CHECK_PLATFORM means serve-check cannot provide Unix process-group custody on this platform. Run on Linux or Darwin. Windows refuses before launching the script; Mac execution requires its own qualification. See snapback4 guide testing.",
        "E_SERVE_NO_JSON" => "# E_SERVE_NO_JSON\n\nE_SERVE_NO_JSON means the npm serve script supplied no complete JSON object line before exit or startup deadline. Emit one readiness object line and keep diagnostics on stderr. An incomplete startup never qualifies the script. See snapback4 guide testing.",
        "E_SERVE_EXTRA_OUTPUT" => "# E_SERVE_EXTRA_OUTPUT\n\nE_SERVE_EXTRA_OUTPUT means the serve script emitted extra, invalid, oversized or unterminated stdout. Use npm run --silent and exactly one JSON object line. Keep credentials out of diagnostics; the report withholds script output. See snapback4 guide testing.",
        "E_SERVE_EARLY_EXIT" => "# E_SERVE_EARLY_EXIT\n\nE_SERVE_EARLY_EXIT means the npm serve script exited before the requested up interval completed. Hold an owned referenced lifetime until SIGTERM, then await host cleanup. A readiness line alone does not qualify uptime. See snapback4 guide testing.",
        "E_SERVE_CHILD_RUNNING" => "# E_SERVE_CHILD_RUNNING\n\nE_SERVE_CHILD_RUNNING means an owned child remained alive after group SIGTERM and the stop grace. Stop every owned host and inspect the driver. Forced group cleanup happens after inspection and cannot make this failed check pass. See snapback4 guide testing.",
        "E_SERVE_DRIVER_EXIT" => "# E_SERVE_DRIVER_EXIT\n\nE_SERVE_DRIVER_EXIT means the checker driver or keeper exited or lost IPC before inspection completed. Investigate the driver failure and rerun. Lost custody never qualifies a serve script. See snapback4 guide testing.",
        "E_SERVE_LOCK_HELD" => "# E_SERVE_LOCK_HELD\n\nE_SERVE_LOCK_HELD means the requested deployment lock remained held after group SIGTERM, or its lock barrier refused. Inspect the intended owner and deployment before rerunning. The observation precedes forced cleanup; the check does not delete a lock. See snapback4 guide testing.",
        "E_SERVE_INSPECTION" => "# E_SERVE_INSPECTION\n\nE_SERVE_INSPECTION means the process-group listing could not be classified. Restore a working ps command and rerun. An unknown group never passes cleanup; only the pinned group is reclaimed. See snapback4 guide testing.",
        "E_SERVE_START" => "# E_SERVE_START\n\nE_SERVE_START means the npm script could not start or its keeper handshake was not received. Check npm and the script name, then rerun. No readiness or custody claim is made without the handshake. See snapback4 guide testing.",

        "E_COMMITTER_REENTRANT" => "# Committer worker reentry\n\nE_COMMITTER_REENTRANT means a committer command tried to submit to its own queue. The nested command was not enqueued or applied. Use an inline member continuation. This is an internal programming error; retrying the request cannot repair it.",
        "E_COMMITTER_STOPPED" => "# Committer stopped before execution\n\nE_COMMITTER_STOPPED means the committer disconnected before this command started execution. The command was not applied. Retry only after the server recovers. A disconnection after execution starts is E_COMMIT_OUTCOME_UNKNOWN instead: reconcile its durable receipt or operation key before retrying. Admitted commands have no acknowledgement timeout.",
        "E_CLOCK_REPORT_INCOMPLETE" => "# Clock report incomplete after advance\n\nE_CLOCK_REPORT_INCOMPLETE means time already advanced but maintenance or reporting failed. The response carries advancedMs and reportIncomplete; it is not retryable and has no Retry-After. Inspect the clock and queued work or use clock drain (0ms). Never repeat the original relative duration to recover the report: that would advance time again. The message retains the underlying reporting failure.",
        "E_STORE_CONFIG" => "# Store configuration\n\nE_STORE_CONFIG means store selectors conflict or the deployment binding is missing or invalid. Use one store selector. Supply the original store URL with explicit schema and HA mode; keep credentials in deployment configuration. Restore the matching immutable release and logical store binding before serving. See snapback4 guide deploy.",
        "E_STORE_OWNERSHIP" => "# Postgres store ownership\n\nE_STORE_OWNERSHIP means the owner token, logical store binding or bounded takeover is no longer valid. A stale token refuses before durable work. Stop admission, acquire ownership on the lease connection and reopen with the acquired token. Lease renewal runs independently of application transactions. See snapback4 guide refusals.",
        "E_COMMIT_OUTCOME_UNKNOWN" => "# Unknown COMMIT outcome\n\nE_COMMIT_OUTCOME_UNKNOWN means COMMIT lost its acknowledgement, a synchronous replication wait was cancelled, or the committer worker disconnected after execution started. Admitted commands wait for their real result without an acknowledgement timeout. The operation may already be durable. Resolve its persisted receipt or operation key before any retry. Automatic retry is disabled; this error is not an execution refusal. The adapter disables timeouts during COMMIT. See snapback4 guide refusals.",
        "E_WORKER_STORE_ID" => "# Worker ledger store identity\n\nE_WORKER_STORE_ID means the completion ledger has no nonempty logical store identity. Repair the store binding before starting workers. Completion filenames are namespaced by that identity, so a replacement store cannot reuse earlier completions. Keep the ledger with the store across releases and backups. See snapback4 guide effects.",
        "E_WORKER_STATE" => "# Postgres worker state location\n\nE_WORKER_STATE means the Postgres completion ledger has no explicitly configured absolute durable state directory. Configure that directory before starting workers. The ledger filename uses the logical store id, and never the Postgres URL. Serve accepts --worker-state-dir or SNAPBACK4_WORKER_STATE_DIR and validates this binding before listening; worker execution remains outside its initial profile. See snapback4 guide effects.",
        "E_WITNESS_APP_SELECTION" => "# Browser proof application selection\n\nE_WITNESS_APP_SELECTION means the proof driver already selected another App instance on this page. The first App stays selected; a later registration cannot replace its receipt observer. Use a separate browser page for the other App. Sign-in and session restoration on the selected App do not change selection. This public same-origin test observer grants no backend authority and is not a confidentiality boundary.",
        "E_CLOCK_HELD" => "# Retained schedule boundary\n\nE_CLOCK_HELD means a saved schedule boundary is ahead of the requested effective schedule window. Nothing advanced. An already processed current window is not-due, not held; repeated advances and zero-time drains remain available. Continue by the reported duration, retain the cumulative offset across restart, or use a fresh staging deployment. allowHeld:true (CLI --allow-held) explicitly accepts the hold; saved boundaries never rewind. See guide staging and guide clock.",
        "E_STORE_UNSUPPORTED" => "# Unavailable store family\n\nE_STORE_UNSUPPORTED names a family the selected store does not yet implement. The unified Postgres engine admits maintained-column evolution plus ordinary table additions, optional/literal-defaulted columns, index changes and table/column retirement and restoration. Deploy with --restore-dormant to reuse retired names. Narrowing, backfills, renames and authority changes retain named refusals before preparation writes; use SQLite for those transitions. Ordinary schema changes in a schema containing durable temporal, read-through or recorded tables wait for their lifecycle support; use SQLite for that combined transition. The retained evaluator's release API still refuses schema evolution (family evolution). Repeating the same activation cannot enable the missing family.",
        "E_STORE_GENERATION" => "# Invalid stored generation\n\nE_STORE_GENERATION means the persisted generation metadata is malformed, non-positive or outside the signed integer range. Opening refuses before trusting that value, and a failed read does not abort its transaction. Restore a known-good store backup before reopening; preserve the current store for operator inspection. Never delete the store to make adoption pass.",
        "E_QUARRY_STATEMENT" => include_str!("why/E_QUARRY_STATEMENT.md"),
        "E_QUARRY_FANOUT" => include_str!("why/E_QUARRY_FANOUT.md"),
        "N_IMMUTABLE_PATCH" => include_str!("why/N_IMMUTABLE_PATCH.md"),
        "E_QUARRY_IMMUTABLE" => include_str!("why/E_QUARRY_IMMUTABLE.md"),
        "N_CASCADE_DORMANT" => include_str!("why/N_CASCADE_DORMANT.md"),

        "E_FOLLOWING_INPUT" | "E_FOLLOWING_DECLARATION" | "E_FOLLOWING_PAGE_SIZE" | "E_FOLLOWING_QUOTA" | "E_FOLLOWING_REQUEST_TOO_SMALL" | "E_FOLLOWING_ROW_TOO_LARGE" => include_str!("why/following-reader.md"),
        "N_RECEIPT_PREDICTION" => include_str!("why/N_RECEIPT_PREDICTION.md"),
        "EMPTY_READ" => include_str!("why/EMPTY_READ.md"),
        "N_SEQUENCE_READ" => include_str!("why/N_SEQUENCE_READ.md"),
        "E_READ_THROUGH_SCAN" => include_str!("why/E_READ_THROUGH_SCAN.md"),
        "E_READ_THROUGH_ADOPT" => include_str!("why/E_READ_THROUGH_ADOPT.md"),
        "E_PARENT_HAS_CHILDREN" => include_str!("why/E_PARENT_HAS_CHILDREN.md"),
        "N_DELETE_RESTRICTED" => include_str!("why/N_DELETE_RESTRICTED.md"),
        "N_DELETE_NEEDS_READ" => include_str!("why/N_DELETE_NEEDS_READ.md"),
        "N_REFERENCE_UNCHECKED" => include_str!("why/N_REFERENCE_UNCHECKED.md"),
        "N_MAINTAIN_AUTHORIZATION" => include_str!("why/N_MAINTAIN_AUTHORIZATION.md"),
        "E_REFERENCED" => include_str!("why/E_REFERENCED.md"),
        "E_REFERENCE_ACTION" => include_str!("why/E_REFERENCE_ACTION.md"),
        "E_CASCADE_BOUND" => include_str!("why/E_CASCADE_BOUND.md"),
        "N_PATCH_CLEARS" => include_str!("why/N_PATCH_CLEARS.md"),
        "N_PROBE_ONLY_READ" => include_str!("why/N_PROBE_ONLY_READ.md"),
        "N_VACUOUS_RULE" => include_str!("why/N_VACUOUS_RULE.md"),
        "N_QUERY_FALLTHROUGH" => include_str!("why/N_QUERY_FALLTHROUGH.md"),
        "N_QUERY_RESERVATION" => include_str!("why/N_QUERY_RESERVATION.md"),
        "E_FRONTEND_SCENARIO" => include_str!("why/E_FRONTEND_SCENARIO.md"),
        "N_UNIQUE_HIDDEN" => include_str!("why/N_UNIQUE_HIDDEN.md"),
        "N_LOOKUP_FILTERED" => include_str!("why/N_LOOKUP_FILTERED.md"),
        "N_LOOKUP_HIDDEN" => include_str!("why/N_LOOKUP_HIDDEN.md"),
        "N_NO_PRODUCTION_WRITER" => include_str!("why/N_NO_PRODUCTION_WRITER.md"),
        "N_UNREADABLE_PROBE" => include_str!("why/N_UNREADABLE_PROBE.md"),
        "N_REQUIRE_HIDDEN" => include_str!("why/N_REQUIRE_HIDDEN.md"),
        "N_QUERY_FILTERED" => include_str!("why/N_QUERY_FILTERED.md"),
        "N_REQUIRE_REFUSED" => include_str!("why/N_REQUIRE_REFUSED.md"),
        "E_READ_THROUGH" => include_str!("why/E_READ_THROUGH.md"),
        "E_ADMISSION" | "E_ADMISSION_STORE" | "E_ADMISSION_TIMEOUT" => include_str!("why/E_ADMISSION.md"),
        "E_ADOPT" => include_str!("why/E_ADOPT.md"),
        "E_CONFLICT" => include_str!("why/E_CONFLICT.md"),
        "E_CONSTRAINT" => include_str!("why/E_CONSTRAINT.md"),
        "E_CURSOR_INDEX" => include_str!("why/E_CURSOR_INDEX.md"),
        "E_EMIT_IN_QUERY" => include_str!("why/E_EMIT_IN_QUERY.md"),
        "E_FIELD" => include_str!("why/E_FIELD.md"),
        "E_ID_REUSED" => include_str!("why/E_ID_REUSED.md"),
        "E_INIT_CONFLICT" => include_str!("why/E_INIT_CONFLICT.md"),
        "E_INPUT" => include_str!("why/E_INPUT.md"),
        "E_INTERNAL" => include_str!("why/E_INTERNAL.md"),
        "E_MAINTAINED_COLUMN" => include_str!("why/E_MAINTAINED_COLUMN.md"),
        "E_NOT_PREDICTABLE" => include_str!("why/E_NOT_PREDICTABLE.md"),
        "E_OP" => include_str!("why/E_OP.md"),
        "E_OP_RESERVED" => include_str!("why/E_OP_RESERVED.md"),
        "E_DIV_ZERO" => include_str!("why/E_DIV_ZERO.md"),
        "E_OVERFLOW" => include_str!("why/E_OVERFLOW.md"),
        "E_PREDICT" => include_str!("why/E_PREDICT.md"),
        "E_QUARRY_AMBIGUOUS" => include_str!("why/E_QUARRY_AMBIGUOUS.md"),
        "E_UNIQUE" => include_str!("why/E_UNIQUE.md"),
        "N_PERSONA_PRINCIPAL" => include_str!("why/N_PERSONA_PRINCIPAL.md"),
        "E_QUARRY_BOUND" => include_str!("why/E_QUARRY_BOUND.md"),
        "E_CHECK_NOTES" => include_str!("why/E_CHECK_NOTES.md"),
        "E_QUARRY_DUPLICATE_RULE" => include_str!("why/E_QUARRY_DUPLICATE_RULE.md"),
        "E_QUARRY_DUPLICATE_FIELD" => include_str!("why/E_QUARRY_DUPLICATE_FIELD.md"),
        "E_QUARRY_KEY_ORDER" => include_str!("why/E_QUARRY_KEY_ORDER.md"),
        "E_QUARRY_LIVE_MAINTAIN_PROBE" => include_str!("why/E_QUARRY_LIVE_MAINTAIN_PROBE.md"),
        "E_QUARRY_MAINTAIN_EXPIRE" => include_str!("why/E_QUARRY_MAINTAIN_EXPIRE.md"),
        "E_QUARRY_MODIFIER_SCOPE" => include_str!("why/E_QUARRY_MODIFIER_SCOPE.md"),
        "E_QUARRY_PLACEMENT" => include_str!("why/E_QUARRY_PLACEMENT.md"),
        "E_QUARRY_POSITIONAL_SCAN" => include_str!("why/E_QUARRY_POSITIONAL_SCAN.md"),
        "E_QUARRY_SELF_EQUALITY" => include_str!("why/E_QUARRY_SELF_EQUALITY.md"),
        "E_QUARRY_SHAPE_JOIN" => include_str!("why/E_QUARRY_SHAPE_JOIN.md"),
        "E_QUARRY_SPREAD" => include_str!("why/E_QUARRY_SPREAD.md"),
        "E_QUARRY_SYNTAX" => include_str!("why/E_QUARRY_SYNTAX.md"),
        "E_QUARRY_RULE_HOP" => include_str!("why/E_QUARRY_RULE_HOP.md"),
        "E_QUARRY_RULE_OPERATOR" => include_str!("why/E_QUARRY_RULE_OPERATOR.md"),
        "E_PROOF_BROWSER" => "# Proof browser dependency\n\nE_PROOF_BROWSER means the proof project cannot resolve playwright-core. Install playwright-core@1.55.1 in the proof project and rerun. The check precedes browser startup, application callbacks and log creation; it changes no application state. See snapback4 guide testing.",
        "E_PROOF_PAGE" => "# Complete proof pages\n\nE_PROOF_PAGE means a bounded traversal saw a refused, loading, malformed, repeated, capped, incomplete, partial-existence or over-limit page. Repair its query, authority or bound and pass each opaque next cursor back unchanged. No partial snapshot is returned. See snapback4 guide testing.",
        "E_DEV_RESET" => "# Development store reset\n\nE_DEV_RESET means an already-bound client observed the replacement store after /dev/reset. Reopen the client after reset. Outstanding writes retain unknown outcomes and are never retried automatically; reconcile them before new writes. See snapback4 guide testing.",
        "E_PROOF_USAGE" => "# Proof helper usage\n\nE_PROOF_USAGE means a proof helper received the wrong argument shape. Call startServe(deployDir, options) with a nonempty directory string first. See snapback4 guide testing.",
        "E_PRODUCTION_ACCOUNTS" => "# Production account provisioning\n\nE_PRODUCTION_ACCOUNTS means provisionAccounts did not find serve on a production deployment with password identity. Staging and development refuse before creating users. Use seedAccounts only on a fresh deploy --staging. See snapback4 guide production.",
        "E_QUARRY_IDENTITY_DUPLICATE" => "# Duplicate identity declaration\n\nE_QUARRY_IDENTITY_DUPLICATE means `use identity` was declared more than once. `use identity` applies to the whole project. Keep one declaration: password, guests, or both. The diagnostic names the first declaration and both method sets. See snapback4 guide production.",
        "E_QUARRY_RESERVED" => include_str!("why/E_QUARRY_RESERVED.md"),
        "E_QUARRY_TYPE" => include_str!("why/E_QUARRY_TYPE.md"),
        "E_QUARRY_UNKNOWN" => include_str!("why/E_QUARRY_UNKNOWN.md"),
        "E_QUARRY_MATCHING_INDEX" => include_str!("why/E_QUARRY_MATCHING_INDEX.md"),
        "E_QUARRY_UNSUPPORTED" => include_str!("why/E_QUARRY_UNSUPPORTED.md"),
        "E_QUARRY_WRITE_TESTS" => include_str!("why/E_QUARRY_WRITE_TESTS.md"),
        "E_QUERY_HELD" => include_str!("why/E_QUERY_HELD.md"),
        "E_FIELD_AUTHORITY" => include_str!("why/E_FIELD_AUTHORITY.md"),
        "E_RULE" => include_str!("why/E_RULE.md"),
        "E_SERVER_REQUIRED" => include_str!("why/E_SERVER_REQUIRED.md"),
        "E_SHAPE_EXCEEDS_METER" => include_str!("why/E_SHAPE_EXCEEDS_METER.md"),
        "E_STRUCTURAL_FANOUT" => include_str!("why/E_STRUCTURAL_FANOUT.md"),
        "E_TYPE" => include_str!("why/E_TYPE.md"),
        "E_UNBOUND_LOOP" => include_str!("why/E_UNBOUND_LOOP.md"),
        "E_UNBOUND_SCAN" => include_str!("why/E_UNBOUND_SCAN.md"),
        "E_WRITE_ID" => include_str!("why/E_WRITE_ID.md"),
        "E_WRITE_ID_REUSE" => include_str!("why/E_WRITE_ID_REUSE.md"),
        "NOT_FOUND" => include_str!("why/NOT_FOUND.md"),
        "E_SEARCH_OPEN" | "N_SEARCH_UNSCOPED" | "N_SEARCH_OPEN" | "N_SEARCH_WORDS" | "N_SEARCH_SHAPE" => include_str!("why/SEARCH.md"),
        "N_CONDITIONAL_COMPLETE" => include_str!("why/N_CONDITIONAL_COMPLETE.md"),
        "E_REDUNDANT_RULE" => include_str!("why/E_REDUNDANT_RULE.md"),
        "N_SWEEP_DEADLINE" => include_str!("why/N_SWEEP_DEADLINE.md"),
        "N_NEVER_COMPLETE" => include_str!("why/N_NEVER_COMPLETE.md"),
        "N_SHAPE_METER" => include_str!("why/N_SHAPE_METER.md"),
        "N_NO_CURSOR" => include_str!("why/N_NO_CURSOR.md"),
        "N_OPTIONAL_FILTER_LIMIT" => include_str!("why/N_OPTIONAL_FILTER_LIMIT.md"),
        "N_HELD_UNKNOWN" => include_str!("why/N_HELD_UNKNOWN.md"),
        "N_SYNC_EMPTY" => include_str!("why/N_SYNC_EMPTY.md"),
        "N_SEEK" => include_str!("why/N_SEEK.md"),
        "N_SPARSE_FILTER" => include_str!("why/N_SPARSE_FILTER.md"),
        "E_WRITE_RECEIPT_EXPIRED" => include_str!("why/E_WRITE_RECEIPT_EXPIRED.md"),
        _ => return None,
    })
}
